import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import "bootstrap/dist/css/bootstrap.min.css";
import "../assets/css/light-bootstrap-dashboard-react.css?v=2.0.0";

import {
  Container,
  Row,
  Col,
  Card,
} from "react-bootstrap";

function Dashboard() {
  // ตั้งค่าเริ่มต้นเป็นกราฟว่างๆ (รอข้อมูลจาก DB)
  const [chartData, setChartData] = useState({
    labels: [],
    series: [[], [], [], []]
  });

  // ฟังก์ชันดึงข้อมูลจาก Database
  const fetchData = async () => {
    try {
      // ยิงไปที่ Backend ของคุณ (Port 3001)
      const response = await fetch('http://localhost:3001/api/chart-data');
      const result = await response.json();

      console.log("Real DB Data:", result); // เช็คค่าจริงใน Console

      // อัปเดตข้อมูลเข้ากราฟทันที (ไม่ว่าจะ 0 หรือเท่าไหร่ก็ตาม)
      if(result && result.series) {
          setChartData(result);
      }

    } catch (error) {
      console.error("Error fetching data:", error);
    }
  };

  useEffect(() => {
    fetchData(); // ดึงครั้งแรก
    const interval = setInterval(fetchData, 5000); // ดึงใหม่ทุก 5 วินาที
    return () => clearInterval(interval);
  }, []);

  // ตั้งค่าดีไซน์กราฟ (เส้นโค้งสวยๆ แบบ Users Behavior)
  const options = {
    lineSmooth: true,  // เปิดเส้นโค้ง
    low: 0,            // เริ่มต้นที่ 0
    high: 20,          // **ปรับเลขนี้** ตามจำนวนคนที่คาดว่าเยอะที่สุด (เช่น 50 หรือ 100)
    showArea: false,   // ไม่ระบายสีพื้นหลัง
    height: "245px",
    axisX: {
      showGrid: false, // ปิดตารางแนวตั้ง
    },
    lineSmooth: window.Chartist.Interpolation.simple({
      divisor: 3
    }),
    showLine: true,
    showPoint: true,
    fullWidth: true,
    chartPadding: {
      right: 50
    }
  };

  // ตั้งค่า Responsive
  const responsiveOptions = [
    [
      "screen and (max-width: 640px)",
      {
        axisX: {
          labelInterpolationFnc: function (value) {
            return value[0];
          },
        },
      },
    ],
  ];

  return (
    <>
      <Container fluid>
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">Passenger Density (Real Database)</Card.Title>
                <p className="card-category">ข้อมูลจริงจากระบบ (07:00 - 22:00)</p>
              </Card.Header>
              <Card.Body>
                <div className="ct-chart" id="chartHours">
                  <ChartistGraph
                    data={chartData}
                    type="Line"
                    options={options}
                    responsiveOptions={responsiveOptions}
                  />
                </div>
              </Card.Body>
              <Card.Footer>
                <div className="legend">
                  <i className="fas fa-circle text-info"></i> วิศวะ (ฟ้า) &nbsp;
                  <i className="fas fa-circle text-danger"></i> วิทยา (แดง) &nbsp;
                  <i className="fas fa-circle text-warning"></i> ศิลปศาสตร์ (ส้ม) &nbsp;
                  <i className="fas fa-circle" style={{color: '#9368E9'}}></i> PKY (ม่วง)
                </div>
                <hr />
                <div className="stats">
                  <i className="fas fa-history"></i> อัปเดตล่าสุดเมื่อสักครู่
                </div>
              </Card.Footer>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
}

export default Dashboard;
